using System;
using Outbreak.Contracts;
using Outbreak.Core;
using Outbreak.Persistence;
public static partial class Program
{
    private static bool VisitedFoodRoom(ActorState actor,int id){if(actor.foodRoomVisits!=null)foreach(FoodRoomVisit visit in actor.foodRoomVisits)if(visit.roomId==id)return true;return false;}
    private static void CheckFoodExplorationCases()
    {
        Check("Food exploration checks an empty room then discovers hidden supplies and saves exactly", () => {
            World w=EncounterScenarios.FoodExplorationTest();w.Step();Require(w.FoodExploration && w.ActorAt(0).foodExploreRoomId==63 && w.ActorAt(0).foodExploreUntilTick==151 && w.ActorAt(0).foodUntilTick==0 && RememberedFood(w.ActorAt(0),12,3)==-2,"Food exploration did not start with the nearest visible entrance without revealing hidden shelves.");World copy=World.Restore(w.Capture());Run(w,30);Run(copy,30);Require(w.ActorAt(0).foodExploreRoomId==0 && VisitedFoodRoom(w.ActorAt(0),63) && w.TerrainAt(5,5)==Terrain.DoorClosed,"Empty room investigation failed completion, memory or physical door closure.");Run(w,120);Run(copy,120);ActorState actor=w.ActorAt(0);Require(actor.hunger<40 && actor.carriedFood+w.ShelfAt(12,3).food==5 && w.ShelfAt(7,7).food==0 && VisitedFoodRoom(actor,63) && VisitedFoodRoom(actor,72) && w.TerrainAt(10,5)==Terrain.DoorClosed,"Explorer failed to discover, search and eat finite food while closing the new refuge.");Require(State(w)==State(copy),"Exploration and its later food trip diverged after saving.");Inspect(w);
        });
        Check("Unseen food quantities cannot choose which room gets investigated", () => {
            SaveDocument s=EncounterScenarios.FoodExplorationTest().Capture();World full=World.Restore(s);WorldMap map=WorldMap.Restore(s.map);map.SetShelf(12,3,0);s.map=map.Capture();World empty=World.Restore(s);for(int i=0;i<121;i++){full.Step();empty.Step();Require(Documents.Encode(full.ActorAt(0))==Documents.Encode(empty.ActorAt(0)) && full.Capture().randomState==empty.Capture().randomState,"Hidden or unopened room stock affected exploration before searching.");}Require(VisitedFoodRoom(full.ActorAt(0),63) && full.ActorAt(0).foodX==12 && full.ActorAt(0).shelfSearchProgress>0,"Explorer did not investigate the empty room before searching the second room's unknown shelf.");
        });
        Check("Food exploration preserves remembered food priority and prior rule generations", () => {
            SaveDocument s=EncounterScenarios.FoodExplorationTest().Capture();WorldMap map=WorldMap.Restore(s.map);map.SetShelf(7,3,1,true);s.map=map.Capture();World w=World.Restore(s);w.Step();Require(w.ActorAt(0).foodExploreRoomId==0 && w.ActorAt(0).foodX==7 && w.ActorAt(0).foodY==3,"Room exploration displaced usable known food.");s=EncounterScenarios.FoodExplorationTest().Capture();s.rulesVersion=EncounterRules.YieldVersion;w=World.Restore(s);w.Step();Require(!w.FoodExploration && w.FoodYieldChoice && w.ActorAt(0).foodExploreRoomId==0 && w.ActorAt(0).foodRoomVisits==null && w.Capture().rulesVersion==EncounterRules.YieldVersion,"Generation 36 silently gained food exploration state.");
        });
        Check("Exploration risk cancellation releases outdoor admission and can return home", () => {
            World w=EncounterScenarios.FoodExplorationTest();w.Step();SaveDocument s=w.Capture();s.actors[0].stress=100;s.actors[0].homeShelterId=72;w=World.Restore(s);Run(w,5);Require(w.ActorAt(0).foodExploreRoomId==0 && w.ActorAt(0).foodExploreUntilTick==0 && w.ActorAt(0).shelterId==72 && VisitedFoodRoom(w.ActorAt(0),63) && w.ShelfAt(12,3).food==6,"An overwhelmed outdoor explorer failed to release its search and return to refuge.");s=EncounterScenarios.FoodExplorationTest().Capture();s.actors[0].hunger=40;s.actors[0].bravery=-3;s.actors[0].stress=20;w=World.Restore(s);w.Step();Require(w.ActorAt(0).foodExploreRoomId==0,"Hunger/bravery tolerance failed to gate an unfamiliar-room trip.");
        });
        Check("Explorers respect full rooms and cannot select entrances hidden behind walls", () => {
            World w=EncounterScenarios.FoodExplorationTest();int id;for(int i=0;i<7;i++)w.TrySpawn(Species.Human,2+i%3,3+i/3,out id);w.Step();Require(w.ActorAt(0).foodExploreRoomId==72,"Explorer reserved a full room.");SaveDocument s=EncounterScenarios.FoodExplorationTest().Capture();s.actors[0].foodRoomVisits=new[]{new FoodRoomVisit{roomId=63,observedTick=0}};WorldMap map=WorldMap.Restore(s.map);for(int y=0;y<7;y++)map.Set(8,y,Terrain.Wall);s.map=map.Capture();w=World.Restore(s);w.Step();Require(w.ActorAt(0).foodExploreRoomId==0 && w.ActorAt(0).shelterId==0,"Explorer selected a reachable but unobserved entrance through a wall.");s=w.Capture();s.actors[0].x=7;s.actors[0].y=5;map=WorldMap.Restore(s.map);map.Set(8,5,Terrain.Grass);s.map=map.Capture();w=World.Restore(s);Run(w,5);Require(w.ActorAt(0).foodExploreRoomId==72,"A newly observable entrance could not be investigated.");
        });
        Check("Room exploration deadlines and recent-room avoidance expire at exact ticks", () => {
            World w=EncounterScenarios.FoodExplorationTest();w.Step();SaveDocument s=w.Capture();s.actors[0].foodExploreUntilTick=2;w=World.Restore(s);w.Step();Require(w.ActorAt(0).foodExploreRoomId==0 && w.ActorAt(0).foodExploreUntilTick==0 && w.ActorAt(0).shelterId==0 && VisitedFoodRoom(w.ActorAt(0),63),"Exploration deadline failed to release its reservation between action opportunities.");s=EncounterScenarios.FoodExplorationTest().Capture();s.actors[0].hunger=0;s.actors[0].foodRoomVisits=new[]{new FoodRoomVisit{roomId=63,observedTick=0},new FoodRoomVisit{roomId=72,observedTick=0}};w=World.Restore(s);Run(w,299);Require(w.ActorAt(0).foodRoomVisits.Length==2,"Room history expired before its deadline.");w.Step();Require(w.ActorAt(0).foodRoomVisits==null,"Room history failed to expire at 300 ticks.");s=w.Capture();s.actors[0].x=7;s.actors[0].y=5;s.actors[0].hunger=80;w=World.Restore(s);w.Step();Require(w.ActorAt(0).foodExploreRoomId==63,"Expired room history permanently prevented investigation.");
        });
        Check("Recent room history advances exploration instead of repeating the nearest empty room", () => {
            SaveDocument s=EncounterScenarios.FoodExplorationTest().Capture();s.actors[0].foodRoomVisits=new[]{new FoodRoomVisit{roomId=63,observedTick=0}};World w=World.Restore(s);w.Step();Require(w.ActorAt(0).foodExploreRoomId==72,"Recently investigated empty room was immediately selected again.");s=EncounterScenarios.FoodExplorationTest().Capture();s.actors[0].foodRoomVisits=new[]{new FoodRoomVisit{roomId=63,observedTick=0},new FoodRoomVisit{roomId=72,observedTick=0}};w=World.Restore(s);w.Step();Require(w.ActorAt(0).foodExploreRoomId==0,"Explorer immediately repeated all recently investigated rooms.");
        });
        Check("Room history retains only eight visits with deterministic oldest-note eviction", () => {
            WorldMap map=new WorldMap(60,8);for(int i=0;i<9;i++){int left=1+5*i;for(int y=2;y<=4;y++)for(int x=left;x<=left+2;x++)map.Set(x,y,x==left+1 && y==3?Terrain.Floor:Terrain.Wall);map.Set(left+2,3,Terrain.DoorClosed);}World w=new World(map,214,encounter:true,hunger:true);int id;w.TrySpawn(Species.Human,42,3,out id);SaveDocument s=w.Capture();ActorState a=s.actors[0];a.hunger=80;a.bravery=3;a.shelterId=223;a.shelterX=42;a.shelterY=3;a.shelterState=ShelterState.Inside;a.foodExploreRoomId=223;a.foodExploreUntilTick=150;a.foodRoomVisits=new FoodRoomVisit[8];for(int i=0;i<8;i++)a.foodRoomVisits[i]=new FoodRoomVisit{roomId=183+5*i,observedTick=0};s.actors[0]=a;w=World.Restore(s);w.Step();Require(w.ActorAt(0).foodRoomVisits.Length==8 && !VisitedFoodRoom(w.ActorAt(0),183) && VisitedFoodRoom(w.ActorAt(0),223),"Ninth room visit did not evict the deterministic oldest note.");World.Restore(w.Capture());
        });
        Check("Room exploration snapshots detach history and reject invalid saved tasks", () => {
            World w=EncounterScenarios.FoodExplorationTest();Run(w,31);ActorState actor=w.ActorAt(0);actor.foodRoomVisits[0].roomId=72;Require(w.ActorAt(0).foodRoomVisits[0].roomId==63,"ActorAt exposed the room notebook.");SaveDocument s=w.Capture();World copy=World.Restore(s);s.actors[0].foodRoomVisits[0].observedTick=0;Require(copy.ActorAt(0).foodRoomVisits[0].observedTick==31 && w.ActorAt(0).foodRoomVisits[0].observedTick==31,"Capture or restore shared mutable room notes.");s=w.Capture();s.rulesVersion=EncounterRules.YieldVersion;Reject(()=>World.Restore(s));s=w.Capture();s.actors[0].foodRoomVisits[0].observedTick=32;Reject(()=>World.Restore(s));s=w.Capture();s.actors[0].foodRoomVisits=new FoodRoomVisit[9];Reject(()=>World.Restore(s));s=w.Capture();s.actors[0].foodExploreUntilTick=50;Reject(()=>World.Restore(s));w=EncounterScenarios.FoodExplorationTest();w.Step();s=w.Capture();s.actors[0].foodExploreRoomId=72;Reject(()=>World.Restore(s));s=w.Capture();s.actors[0].foodExploreUntilTick=152;Reject(()=>World.Restore(s));s=w.Capture();s.actors[0].foodExploreUntilTick=1;Reject(()=>World.Restore(s));s=w.Capture();s.actors[0].foodRoomVisits=new[]{new FoodRoomVisit{roomId=999,observedTick=0}};Reject(()=>World.Restore(s));
        });
        Check("Turning clears active exploration and remembered room history", () => {
            World w=EncounterScenarios.FoodExplorationTest();w.Step();SaveDocument s=w.Capture();s.actors[0].foodRoomVisits=new[]{new FoodRoomVisit{roomId=72,observedTick=0}};s.actors[0].turnAtTick=2;w=World.Restore(s);w.Step();Require(w.ActorAt(0).species==Species.Zombie && w.ActorAt(0).foodExploreRoomId==0 && w.ActorAt(0).foodExploreUntilTick==0 && w.ActorAt(0).foodRoomVisits==null,"Turning retained human room exploration state.");World.Restore(w.Capture());
        });
    }
}
